UPDATE user_token_account
SET reserved_tokens = reserved_tokens + #{tokens}, version = version + 1
WHERE id = #{accountId}
  AND status = '0'
  AND unlimited = '0'
  AND total_tokens - used_tokens - reserved_tokens >= #{tokens}

UPDATE user_token_account
SET reserved_tokens = reserved_tokens - #{reservedTokens},
    used_tokens = used_tokens + #{chargedTokens},
    version = version + 1
WHERE id = #{accountId}
  AND status = '0'
  AND unlimited = '0'
  AND reserved_tokens >= #{reservedTokens}
  AND total_tokens - used_tokens >= #{chargedTokens}

UPDATE user_token_account
SET reserved_tokens = reserved_tokens - #{reservedTokens}, version = version + 1
WHERE id = #{accountId}
  AND reserved_tokens >= #{reservedTokens}
